    ACAI("acai", Color(0xFF802F7C)),
    GOIABA("goiaba", Color(0xFFC52A7A)),
    PITANGA("pitanga", Color(0xFFBC4500)),
    MARACUJA("maracuja", Color(0xFF7B6C00)),
    JENIPAPO("jenipapo", Color(0xFF005678)),
